CREATE POLICY "patients read own medical documents" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'medical-documents' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "patients upload own medical documents" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'medical-documents' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "patients update own medical documents" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'medical-documents' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "patients delete own medical documents" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'medical-documents' AND (storage.foldername(name))[1] = auth.uid()::text);